def input_embeddings(self, seq: torch.Tensor) -> torch.Tensor:
    matches = seq.unsqueeze(2).eq(seq.unsqueeze(1))
    repeated = matches.tril(diagonal=-1).any(dim=-1) & seq.ne(0)
    emb = self.item_emb(seq)
    scale = 1.0 + 0.1 * repeated.to(dtype=emb.dtype)
    return self.dropout(emb * scale.unsqueeze(-1))

def encode(self, seq: torch.Tensor) -> torch.Tensor:
    emb = self.input_embeddings(seq)
